/* Compact match workspace. Paths use normalized coordinates independent of screen size. */
const originalBind = bind;
liveView = function(g) {
  if (!g) return `<div class="topline"><div><div class="eyebrow">Bereit für den Anpfiff</div><h1>Jeder Wurf erzählt etwas.</h1><p class="muted">Erfasse dein Spiel. Entdecke die Muster.</p></div><button class="primary" data-action="newGame">＋ Neues Spiel</button></div><div class="card empty"><div class="empty-symbol">◎</div><h2>Deine Analyse beginnt hier</h2><p>Lege zuerst zwei Mannschaften und ein Spiel an.</p><button style="margin-top:20px" data-action="newTeam">Mannschaft anlegen</button>${db.games.length?'<button data-tab="games">Spiele öffnen</button>':''}</div>`;
  const goals=id=>g.shots.filter(s=>s.team===id&&s.result==='Tor').length;
  const path=draft.path||[], ready=Boolean(draft.player&&path.length>1&&draft.zone!=null&&draft.result);
  return `<section class="match-workspace" aria-label="Spielerfassung"><div class="match-bar"><button data-tab="games" class="back-button">‹ Spiele</button><div class="match-teams"><span>${esc(teamName(g.home))}</span><strong>${goals(g.home)} : ${goals(g.away)}</strong><span>${esc(teamName(g.away))}</span></div><div class="match-timer"><input id="clock" class="clock-input" aria-label="Spielzeit Minuten und Sekunden" value="${time(elapsed)}" inputmode="numeric"><button data-action="clock" class="${running?'':'primary'}">${running?'Ⅱ Pause':'▶ Start'}</button><button data-action="period">${g.period||1}. HZ ⇄</button></div><button data-tab="analysis" class="analysis-shortcut">Auswertung ↗</button></div><div class="match-instructions"><span>${editId?'Wurf korrigieren':'Live-Erfassung'}${g.finished?' · Spiel abgeschlossen':''}</span><span class="${draft.player?'done':''}">1 Spieler</span><span class="${path.length>1?'done':''}">2 Laufweg zeichnen</span><span class="${draft.zone!=null?'done':''}">3 Torfeld</span><span class="${draft.result?'done':''}">4 Ergebnis & speichern</span></div><div class="match-grid"><aside class="roster-panel"><div class="team-switch">${[g.home,g.away].map(id=>`<button data-team="${id}" class="${selectedTeam===id?'active':''}">${esc(teamName(id))}</button>`).join('')}</div><div class="roster-heading">Spieler wählen</div><div class="match-players">${(team(selectedTeam)?.players||[]).map(p=>`<button data-player="${p.number}" class="${draft.player===p.number?'active':''}" title="${esc(p.name)}"><b>${p.number}</b><small>${esc(p.name||'Spieler')}</small></button>`).join('')}<button data-player="?" class="${draft.player==='?'?'active':''}"><b>?</b><small>Unbekannt</small></button></div><button class="roster-edit" data-editteam="${selectedTeam}">Kader bearbeiten</button></aside><div class="field-column"><div class="field-space"><div class="drawing-field" id="drawing-field"><img src="/handballfeld.jpg" alt="Handballfeld mit neun Torsegmenten, aus Sicht des Werfers" draggable="false"><svg id="run-path" viewBox="0 0 1536 1024" preserveAspectRatio="none" aria-label="Zeichenfläche für den Laufweg"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#123e31"/></marker></defs><polyline id="path-shadow" fill="none" stroke="#fff" stroke-width="14" stroke-linecap="round" stroke-linejoin="round"/><polyline id="path-line" fill="none" stroke="#123e31" stroke-width="8" stroke-linecap="round" stroke-linejoin="round" marker-end="url(#arrow)"/><circle id="path-start" r="12" fill="#d6f36b" stroke="#123e31" stroke-width="5" visibility="hidden"/></svg><div class="goal-overlay" aria-label="Torsegment auswählen">${zones.map((z,i)=>`<button data-target="${i}" aria-label="${z}" ${path.length<2?'disabled':''} class="${draft.zone===i?'selected':''}"><span>${draft.zone===i?'✓':i+1}</span></button>`).join('')}</div>${!draft.player?'<div class="field-hint">← Zuerst einen Spieler auswählen</div>':!path.length?'<div class="field-hint">Laufweg mit dem Stift auf dem Spielfeld zeichnen</div>':''}</div></div><div class="field-tools"><span id="path-status">${draft.zone!=null?zones[draft.zone]:path.length>1?'Jetzt eines der neun Torfelder antippen':'Links und rechts aus Sicht des Werfers'}</span><button id="clear-path" ${!path.length?'disabled':''}>↶ Laufweg neu</button></div></div><aside class="outcome-panel"><div><div class="eyebrow">${editId?'Korrektur':'Aktueller Wurf'}</div><h2>${draft.player?'#'+esc(draft.player):'Spieler wählen'}</h2><p class="muted">${esc(draft.player?playerName(selectedTeam,draft.player)||teamName(selectedTeam):'Dann Laufweg & Torfeld')}</p></div><div class="outcome-buttons">${results.map(r=>`<button data-result="${r}" class="${draft.result===r?'active':''}">${r==='Tor'?'● ':''}${r}</button>`).join('')}</div><div class="match-save"><button class="primary" data-action="saveShot" ${!ready?'disabled':''}>${editId?'Änderung speichern':'✓ Wurf speichern'}</button><button data-action="resetDraft">Verwerfen</button></div><button class="history-button" id="shot-history">Würfe ansehen <span>${g.shots.length}</span></button><button class="finish-button" data-action="finish">${g.finished?'Spiel wieder öffnen':'Spiel abschließen'}</button></aside></div><div class="match-footnote"><span>Lokal gespeichert · Nach dem Spiel Sicherung exportieren</span><span>Stift, Finger oder Maus · ${esc(g.date)}</span></div></section>`;
};
function drawPath(){const points=(draft.path||[]).map(p=>`${p.x*1536},${p.y*1024}`).join(' ');$('#path-line')?.setAttribute('points',points);$('#path-shadow')?.setAttribute('points',points);const start=$('#path-start');if(start&&draft.path?.length){start.setAttribute('cx',draft.path[0].x*1536);start.setAttribute('cy',draft.path[0].y*1024);start.setAttribute('visibility','visible')}}
bind = function(){
  originalBind();
  document.body.classList.toggle('in-match',tab==='live'&&Boolean(game()));
  if(tab!=='live'||!game())return;
  document.querySelectorAll('[data-team]').forEach(b=>b.onclick=()=>{if(selectedTeam!==b.dataset.team){selectedTeam=b.dataset.team;draft={};render()}});
  document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>{if(draft.player!==b.dataset.player){draft={player:b.dataset.player};render()}});
  drawPath();
  document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{if(draft.path?.length>1){draft.zone=Number(b.dataset.target);render()}});
  $('#clear-path').onclick=()=>{draft.path=[];draft.zone=null;delete draft.throwTime;render()};
  const svg=$('#run-path');let pointer=null;
  function point(e){const r=svg.getBoundingClientRect();return {x:Math.min(1,Math.max(0,(e.clientX-r.left)/r.width)),y:Math.min(1,Math.max(0,(e.clientY-r.top)/r.height))}}
  svg.onpointerdown=e=>{if(pointer!==null||!e.isPrimary||e.button!==0)return;if(!draft.player){toast('Bitte zuerst einen Spieler wählen.');return}const p=point(e);if(p.y<.29){toast('Den Laufweg bitte auf dem Spielfeld beginnen.');return}e.preventDefault();pointer=e.pointerId;svg.setPointerCapture(pointer);draft.path=[p];draft.zone=null;draft.throwTime=time(elapsed);drawPath()};
  svg.onpointermove=e=>{if(e.pointerId!==pointer)return;e.preventDefault();const p=point(e),last=draft.path.at(-1);if(Math.hypot((p.x-last.x)*1536,(p.y-last.y)*1024)>3){draft.path.push(p);drawPath()}};
  function end(e){if(e.pointerId!==pointer)return;pointer=null;if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);if(draft.path.length<2){draft.path=[];delete draft.throwTime}render()}
  svg.onpointerup=end;
  svg.onpointercancel=e=>{if(e.pointerId!==pointer)return;pointer=null;draft.path=[];draft.zone=null;delete draft.throwTime;render();toast('Zeichnung unterbrochen. Bitte erneut zeichnen.')};
  $('#shot-history').onclick=()=>{const g=game();modal(`<div class="card-head"><h2>Alle Würfe (${g.shots.length})</h2><button data-close>Schließen</button></div><div id="history-list">${g.shots.slice().reverse().map(s=>`<button class="history-entry" data-history="${s.id}"><b>${esc(s.time)} · #${esc(s.player)} · ${esc(s.result)}</b><small>${esc(teamName(s.team))} · ${s.zone==null?'Ziel offen':zones[s.zone]}</small></button>`).join('')||'<p class="muted">Noch keine Würfe erfasst.</p>'}</div>`);document.querySelectorAll('[data-history]').forEach(b=>b.onclick=()=>{const s=g.shots.find(s=>s.id===b.dataset.history);modal(`<h2>Wurf · ${esc(s.time)} · #${esc(s.player)}</h2><p style="margin:16px 0">${esc(s.result)} · ${s.zone==null?'Ziel offen':zones[s.zone]}</p><div class="dialog-actions"><button data-close>Schließen</button><button class="danger" id="delete-history">Löschen</button><button class="primary" id="correct-history">Korrigieren</button></div>`);$('#correct-history').onclick=()=>{editId=s.id;selectedTeam=s.team;draft={...s,path:s.path?.map(p=>({...p}))||[]};$('#dialog').close();render()};$('#delete-history').onclick=()=>{if(confirm('Diesen Wurf löschen?')){g.shots=g.shots.filter(x=>x.id!==s.id);persist();$('#dialog').close();render()}}})};
};
actions.saveShot=()=>{if(!draft.player||!draft.result||draft.zone==null||draft.path?.length<2||!draft.path)return;saveShot()};
render();
